1	//! A Rust port of `tsl::hopscotch_map`, written against `std` only.
2	//!
3	//! Module map:
4	//!
5	//! * [`hash`] — the deterministic, libstdc++-flavored hasher (identity for integers).
6	//! * [`bucket`] — one slot: neighborhood bitmap, overflow flag, optional entry.
7	//! * [`table`] — the hopscotch algorithm (probe, hop/displace, spill, grow).
8	//! * [`iter`] — iterators over slots followed by the overflow list.
9	//! * [`hopscotch_map`] — the public [`HopscotchMap`] facade mirroring the C++ API.
10	
11	// The map is a general-purpose container: it intentionally exposes more API than the entry binary
12	// happens to call, so the unused-code lint would fire on the rest of the library surface.
13	#![allow(dead_code)]
14	
15	pub mod bucket;
16	pub mod hash;
17	pub mod hopscotch_map;
18	pub mod iter;
19	pub mod table;
20	
21	pub use hash::{CppStdHash, CppStdHasher};
22	pub use hopscotch_map::HopscotchMap;
23

1	//! A single hopscotch bucket: a neighborhood bitmap plus an optional stored entry.
2	//!
3	//! Hopscotch hashing stores, for every *home* bucket `i`, a bitmap describing which of the
4	//! `NEIGHBORHOOD_SIZE` slots starting at `i` currently hold an entry whose home bucket is `i`.
5	//! The entry slot itself is independent of the bitmap: bucket `i`'s `entry` may belong to some
6	//! earlier home bucket `i - k`.
7	//!
8	//! Layout of [`Bucket::infos`] (a `u64`):
9	//!
10	//! ```text
11	//!  bit 63          bit 62        bits 61..0
12	//! +--------+-------------------+-----------------------------------+
13	//! | unused | overflow present  | neighborhood presence bitmap      |
14	//! +--------+-------------------+-----------------------------------+
15	//! ```
16	//!
17	//! Bit `j` of the neighborhood bitmap (`j` in `0..NEIGHBORHOOD_SIZE`) means "the slot at
18	//! `self_index + j` holds an entry whose home bucket is `self_index`".  The overflow bit means
19	//! "at least one entry whose home bucket is `self_index` lives in the overflow list".
20	
21	/// Number of slots in a bucket's neighborhood.
22	///
23	/// Matches the default `NeighborhoodSize` of `tsl::hopscotch_map` (62), which leaves room in a
24	/// 64-bit word for the overflow flag.
25	pub const NEIGHBORHOOD_SIZE: usize = 62;
26	
27	/// Mask covering the neighborhood presence bits.
28	const NEIGHBORHOOD_MASK: u64 = (1u64 << NEIGHBORHOOD_SIZE) - 1;
29	
30	/// Flag bit recording that this home bucket has spilled into the overflow list.
31	const OVERFLOW_BIT: u64 = 1u64 << NEIGHBORHOOD_SIZE;
32	
33	/// One slot of the hopscotch table.
34	#[derive(Clone, Debug)]
35	pub struct Bucket<K, V> {
36	    infos: u64,
37	    entry: Option<(K, V)>,
38	}
39	
40	impl<K, V> Bucket<K, V> {
41	    /// An empty bucket with an empty neighborhood and no overflow.
42	    pub const fn new() -> Self {
43	        Bucket { infos: 0, entry: None }
44	    }
45	
46	    /// `true` if this slot currently stores no entry.
47	    #[inline]
48	    pub fn is_empty(&self) -> bool {
49	        self.entry.is_none()
50	    }
51	
52	    /// Borrows the stored entry, if any.
53	    #[inline]
54	    pub fn entry(&self) -> Option<&(K, V)> {
55	        self.entry.as_ref()
56	    }
57	
58	    /// Mutably borrows the stored entry, if any.
59	    #[inline]
60	    pub fn entry_mut(&mut self) -> Option<&mut (K, V)> {
61	        self.entry.as_mut()
62	    }
63	
64	    /// Consumes the bucket, yielding the stored entry.
65	    #[inline]
66	    pub fn into_entry(self) -> Option<(K, V)> {
67	        self.entry
68	    }
69	
70	    /// Stores `(key, value)` in this slot.
71	    ///
72	    /// # Panics
73	    /// Panics if the slot is already occupied; callers must only fill empty slots.
74	    #[inline]
75	    pub fn set_entry(&mut self, key: K, value: V) {
76	        debug_assert!(self.entry.is_none(), "overwriting an occupied hopscotch slot");
77	        self.entry = Some((key, value));
78	    }
79	
80	    /// Removes and returns the stored entry.
81	    #[inline]
82	    pub fn take_entry(&mut self) -> Option<(K, V)> {
83	        self.entry.take()
84	    }
85	
86	    /// Raw neighborhood presence bitmap (overflow flag masked off).
87	    #[inline]
88	    pub fn neighborhood_bits(&self) -> u64 {
89	        self.infos & NEIGHBORHOOD_MASK
90	    }
91	
92	    /// `true` if the slot `offset` positions after this bucket holds one of its entries.
93	    #[inline]
94	    pub fn is_present(&self, offset: usize) -> bool {
95	        debug_assert!(offset < NEIGHBORHOOD_SIZE);
96	        self.infos & (1u64 << offset) != 0
97	    }
98	
99	    /// Records that the slot `offset` positions away now holds one of this bucket's entries.
100	    #[inline]
101	    pub fn set_present(&mut self, offset: usize) {
102	        debug_assert!(offset < NEIGHBORHOOD_SIZE);
103	        debug_assert!(!self.is_present(offset), "neighborhood bit set twice");
104	        self.infos |= 1u64 << offset;
105	    }
106	
107	    /// Clears the presence bit for `offset`.
108	    #[inline]
109	    pub fn clear_present(&mut self, offset: usize) {
110	        debug_assert!(offset < NEIGHBORHOOD_SIZE);
111	        debug_assert!(self.is_present(offset), "clearing an unset neighborhood bit");
112	        self.infos &= !(1u64 << offset);
113	    }
114	
115	    /// `true` if entries homed here may live in the overflow list.
116	    #[inline]
117	    pub fn has_overflow(&self) -> bool {
118	        self.infos & OVERFLOW_BIT != 0
119	    }
120	
121	    /// Marks this home bucket as having spilled into the overflow list.
122	    #[inline]
123	    pub fn set_overflow(&mut self) {
124	        self.infos |= OVERFLOW_BIT;
125	    }
126	
127	    /// Clears the overflow flag.
128	    #[inline]
129	    pub fn clear_overflow(&mut self) {
130	        self.infos &= !OVERFLOW_BIT;
131	    }
132	
133	    /// Number of entries homed at this bucket that live inside the table.
134	    #[inline]
135	    pub fn neighborhood_len(&self) -> u32 {
136	        self.neighborhood_bits().count_ones()
137	    }
138	}
139	
140	impl<K, V> Default for Bucket<K, V> {
141	    fn default() -> Self {
142	        Bucket::new()
143	    }
144	}
145	
146	/// Iterator over the set offsets of a neighborhood bitmap, ascending.
147	pub struct NeighborhoodOffsets {
148	    bits: u64,
149	}
150	
151	impl NeighborhoodOffsets {
152	    /// Iterates the set presence offsets of `bucket`.
153	    #[inline]
154	    pub fn new<K, V>(bucket: &Bucket<K, V>) -> Self {
155	        NeighborhoodOffsets { bits: bucket.neighborhood_bits() }
156	    }
157	}
158	
159	impl Iterator for NeighborhoodOffsets {
160	    type Item = usize;
161	
162	    #[inline]
163	    fn next(&mut self) -> Option<usize> {
164	        if self.bits == 0 {
165	            return None;
166	        }
167	        let offset = self.bits.trailing_zeros() as usize;
168	        self.bits &= self.bits - 1; // clear lowest set bit
169	        Some(offset)
170	    }
171	}
172	
173	#[cfg(test)]
174	mod tests {
175	    use super::*;
176	
177	    #[test]
178	    fn overflow_bit_does_not_leak_into_neighborhood() {
179	        let mut b: Bucket<i32, i32> = Bucket::new();
180	        b.set_overflow();
181	        assert!(b.has_overflow());
182	        assert_eq!(b.neighborhood_bits(), 0);
183	        b.set_present(NEIGHBORHOOD_SIZE - 1);
184	        assert!(b.has_overflow());
185	        assert!(b.is_present(NEIGHBORHOOD_SIZE - 1));
186	        assert_eq!(b.neighborhood_len(), 1);
187	        b.clear_overflow();
188	        assert!(!b.has_overflow());
189	        assert!(b.is_present(NEIGHBORHOOD_SIZE - 1));
190	    }
191	
192	    #[test]
193	    fn presence_bits_round_trip() {
194	        let mut b: Bucket<i32, i32> = Bucket::new();
195	        for off in [0usize, 1, 5, 31, 61] {
196	            b.set_present(off);
197	        }
198	        let offsets: Vec<usize> = NeighborhoodOffsets::new(&b).collect();
199	        assert_eq!(offsets, vec![0, 1, 5, 31, 61]);
200	        b.clear_present(5);
201	        let offsets: Vec<usize> = NeighborhoodOffsets::new(&b).collect();
202	        assert_eq!(offsets, vec![0, 1, 31, 61]);
203	        assert_eq!(b.neighborhood_len(), 4);
204	    }
205	
206	    #[test]
207	    fn entry_round_trip() {
208	        let mut b: Bucket<i32, i32> = Bucket::new();
209	        assert!(b.is_empty());
210	        b.set_entry(3, 33);
211	        assert!(!b.is_empty());
212	        assert_eq!(b.entry(), Some(&(3, 33)));
213	        b.entry_mut().unwrap().1 = 44;
214	        assert_eq!(b.take_entry(), Some((3, 44)));
215	        assert!(b.is_empty());
216	    }
217	
218	    #[test]
219	    fn neighborhood_size_fits_with_overflow_flag() {
220	        assert!(NEIGHBORHOOD_SIZE < 64);
221	        assert_eq!(NEIGHBORHOOD_MASK & OVERFLOW_BIT, 0);
222	        assert_eq!(NEIGHBORHOOD_MASK.count_ones() as usize, NEIGHBORHOOD_SIZE);
223	    }
224	}
