1	//! Hashing support for [`HopscotchMap`](crate::tsl::hopscotch_map::HopscotchMap).
2	//!
3	//! The C++ original instantiates `tsl::hopscotch_map<int, int>`, which defaults to
4	//! `std::hash<int>`.  In libstdc++ `std::hash` for every integral type is the *identity*
5	//! function (`static_cast<size_t>(value)`), so key `i` always lands in bucket
6	//! `i & (bucket_count - 1)` of a power-of-two table.
7	//!
8	//! To reproduce that bucket layout (and therefore the same neighborhood / displacement /
9	//! overflow behavior) this module provides [`CppStdHasher`], a `std::hash::Hasher` whose
10	//! integer writes are the identity, plus a deterministic FNV-1a fallback for byte slices
11	//! (`&str`, `String`, `Vec<u8>`, ...) so that non-integer keys still hash sensibly.
12	//!
13	//! Determinism is deliberate: unlike `std::collections::hash_map::RandomState` there is no
14	//! per-process seed, so a given key set always produces the same table layout, which makes
15	//! the hopscotch invariants unit-testable.
16	
17	use std::hash::{BuildHasher, Hash, Hasher};
18	
19	/// FNV-1a 64-bit offset basis.
20	const FNV_OFFSET_BASIS: u64 = 0xcbf2_9ce4_8422_2325;
21	/// FNV-1a 64-bit prime.
22	const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;
23	
24	/// A deterministic `Hasher` that mirrors libstdc++'s `std::hash`.
25	///
26	/// * The first integer written is used *verbatim* (identity hash), matching
27	///   `std::hash<int>::operator()` which is `static_cast<size_t>(value)`.
28	/// * Subsequent writes (tuples, structs, the trailing `0xff` that `Hash for str` emits) are
29	///   folded in with a multiply-xor mix so composite keys still spread out.
30	/// * Byte slices use FNV-1a, standing in for libstdc++'s `_Hash_bytes` (Murmur) helper.
31	#[derive(Clone, Copy, Debug)]
32	pub struct CppStdHasher {
33	    state: u64,
34	    /// Number of `write*` calls seen so far; `0` selects the identity fast path.
35	    writes: u32,
36	}
37	
38	impl CppStdHasher {
39	    /// Creates a fresh hasher.
40	    pub const fn new() -> Self {
41	        CppStdHasher { state: 0, writes: 0 }
42	    }
43	
44	    /// Folds one integer into the state.
45	    ///
46	    /// The very first integer is stored unchanged (identity hash); later ones are mixed so
47	    /// that `(a, b)` and `(b, a)` do not collide.
48	    #[inline]
49	    fn feed_int(&mut self, value: u64) {
50	        if self.writes == 0 {
51	            self.state = value;
52	        } else {
53	            self.state = mix64(self.state ^ value).wrapping_mul(FNV_PRIME);
54	        }
55	        self.writes = self.writes.wrapping_add(1);
56	    }
57	}
58	
59	impl Default for CppStdHasher {
60	    fn default() -> Self {
61	        CppStdHasher::new()
62	    }
63	}
64	
65	/// A 64-bit avalanche mix (the finalizer from SplitMix64 / MurmurHash3).
66	#[inline]
67	const fn mix64(mut x: u64) -> u64 {
68	    x ^= x >> 33;
69	    x = x.wrapping_mul(0xff51_afd7_ed55_8ccd);
70	    x ^= x >> 33;
71	    x = x.wrapping_mul(0xc4ce_b9fe_1a85_ec53);
72	    x ^= x >> 33;
73	    x
74	}
75	
76	impl Hasher for CppStdHasher {
77	    #[inline]
78	    fn finish(&self) -> u64 {
79	        self.state
80	    }
81	
82	    #[inline]
83	    fn write(&mut self, bytes: &[u8]) {
84	        let mut h = if self.writes == 0 {
85	            FNV_OFFSET_BASIS
86	        } else {
87	            mix64(self.state ^ FNV_OFFSET_BASIS)
88	        };
89	        for &b in bytes {
90	            h ^= b as u64;
91	            h = h.wrapping_mul(FNV_PRIME);
92	        }
93	        self.state = h;
94	        self.writes = self.writes.wrapping_add(1);
95	    }
96	
97	    // ---- identity integer paths (this is what makes `std::hash<int>` behavior appear) ----
98	
99	    #[inline]
100	    fn write_u8(&mut self, i: u8) {
101	        self.feed_int(i as u64)
102	    }
103	    #[inline]
104	    fn write_u16(&mut self, i: u16) {
105	        self.feed_int(i as u64)
106	    }
107	    #[inline]
108	    fn write_u32(&mut self, i: u32) {
109	        self.feed_int(i as u64)
110	    }
111	    #[inline]
112	    fn write_u64(&mut self, i: u64) {
113	        self.feed_int(i)
114	    }
115	    #[inline]
116	    fn write_usize(&mut self, i: usize) {
117	        self.feed_int(i as u64)
118	    }
119	    #[inline]
120	    fn write_u128(&mut self, i: u128) {
121	        // libstdc++ folds the two halves of a 128-bit integer together.
122	        self.feed_int((i as u64) ^ ((i >> 64) as u64))
123	    }
124	
125	    // Signed writes sign-extend first, exactly like `static_cast<size_t>(negative_int)`.
126	    #[inline]
127	    fn write_i8(&mut self, i: i8) {
128	        self.feed_int(i as i64 as u64)
129	    }
130	    #[inline]
131	    fn write_i16(&mut self, i: i16) {
132	        self.feed_int(i as i64 as u64)
133	    }
134	    #[inline]
135	    fn write_i32(&mut self, i: i32) {
136	        self.feed_int(i as i64 as u64)
137	    }
138	    #[inline]
139	    fn write_i64(&mut self, i: i64) {
140	        self.feed_int(i as u64)
141	    }
142	    #[inline]
143	    fn write_isize(&mut self, i: isize) {
144	        self.feed_int(i as i64 as u64)
145	    }
146	    #[inline]
147	    fn write_i128(&mut self, i: i128) {
148	        self.feed_int((i as u64) ^ ((i >> 64) as u64))
149	    }
150	}
