152	/// `BuildHasher` producing [`CppStdHasher`]; the default hasher of the map.
153	#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
154	pub struct CppStdHash;
155	
156	impl BuildHasher for CppStdHash {
157	    type Hasher = CppStdHasher;
158	
159	    #[inline]
160	    fn build_hasher(&self) -> CppStdHasher {
161	        CppStdHasher::new()
162	    }
163	}
164	
165	/// Hashes `key` with `build_hasher`, returning the raw 64-bit digest.
166	#[inline]
167	pub fn hash_of<K, S>(build_hasher: &S, key: &K) -> u64
168	where
169	    K: Hash + ?Sized,
170	    S: BuildHasher,
171	{
172	    let mut hasher = build_hasher.build_hasher();
173	    key.hash(&mut hasher);
174	    hasher.finish()
175	}
