177	#[cfg(test)]
178	mod tests {
179	    use super::*;
180	
181	    #[test]
182	    fn integers_hash_to_themselves() {
183	        for i in 0..1000i32 {
184	            assert_eq!(hash_of(&CppStdHash, &i), i as u64, "identity hash for {}", i);
185	        }
186	        assert_eq!(hash_of(&CppStdHash, &0u64), 0);
187	        assert_eq!(hash_of(&CppStdHash, &7usize), 7);
188	    }
189	
190	    #[test]
191	    fn negative_integers_sign_extend_like_static_cast() {
192	        assert_eq!(hash_of(&CppStdHash, &-1i32), u64::MAX);
193	        assert_eq!(hash_of(&CppStdHash, &-5i32), (-5i64) as u64);
194	    }
195	
196	    #[test]
197	    fn bool_and_char_follow_their_integer_writes() {
198	        assert_eq!(hash_of(&CppStdHash, &false), 0);
199	        assert_eq!(hash_of(&CppStdHash, &true), 1);
200	        assert_eq!(hash_of(&CppStdHash, &'A'), 65);
201	    }
202	
203	    #[test]
204	    fn strings_are_deterministic_and_distinct() {
205	        let a = hash_of(&CppStdHash, "hello");
206	        let b = hash_of(&CppStdHash, "hello");
207	        let c = hash_of(&CppStdHash, "world");
208	        assert_eq!(a, b);
209	        assert_ne!(a, c);
210	    }
211	
212	    #[test]
213	    fn tuples_are_order_sensitive() {
214	        let ab = hash_of(&CppStdHash, &(1i32, 2i32));
215	        let ba = hash_of(&CppStdHash, &(2i32, 1i32));
216	        assert_ne!(ab, ba);
217	    }
218	
219	    #[test]
220	    fn mix64_is_a_bijection_on_sampled_points() {
221	        // Sanity: the finalizer must not collapse distinct inputs in the sampled range.
222	        let mut seen = std::collections::HashSet::new();
223	        for i in 0..2000u64 {
224	            assert!(seen.insert(mix64(i)));
225	        }
226	    }
227	}
